import loggingimport os.pathimport asynciofrom discord import Colorfrom print_color import printfrom discord.ext import commandsimport yt_dlpimport jsonfrom utils.EmbedGeneratorUtil import EmbedGeneratorfrom utils.custom.loggers.YTDLPLogger import YTDLPLoggerfrom utils.custom.views.PlayDownloadedSongButtonView import PlayDownloadedSongButtonViewclass DownloadSongCommand(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot        self.logger = logging.getLogger('discord')        self.songs_dir = "/Users/eddie/PycharmProjects/FingerBangThePoonTang2Bot/songs/"        self.songs_info_dir = "/Users/eddie/PycharmProjects/FingerBangThePoonTang2Bot/songs_info/"        self.url = None        self.info = None        self.search_query = None        self.ydl_opts = {            'format': 'bestaudio/best',            'postprocessors': [{                'key': 'FFmpegExtractAudio',                'preferredcodec': 'mp3',  # or 'opus', 'webm'                'preferredquality': 'best',  # or 'best'            }],            'outtmpl': '/Users/eddie/PycharmProjects/FingerBangThePoonTang2Bot/songs/%(id)s.%(ext)s',            # Specify local directory and filename format            'noplaylist': True,  # Prevent downloading entire playlists            'logger': YTDLPLogger(),            'quiet': True,            'noprogress': True,            'newline': True,            'dump_single_json': True,        }    @commands.command(name="dlsong", help="Downloads A Song From Youtube And Stores It Locally, For Later Playback.")    async def download_song(self, ctx: commands.Context, *, search_query: str = commands.Parameter('search_query', description="The Query To Search Youtube.", kind=commands.Parameter.POSITIONAL_OR_KEYWORD)):        if search_query is None:            raise commands.MissingRequiredArgument(param=commands.Parameter(name="search_query", description="The Query To Search Youtube", kind=commands.Parameter.POSITIONAL_OR_KEYWORD))        self.search_query = search_query        embed = EmbedGenerator(self.bot).generate_simple_message_embed(description=f"Searching For '{search_query}' And Attempting To Download! This May Take Some Time.", colour=Color.blurple())        print(f"Youtube for: {search_query}", tag="SEARCHING", tag_color="blue", color="white")        self.logger.info(msg=f"[SEARCHING] Youtube For: {search_query}")        msg_ = await ctx.reply(embed=embed, mention_author=False)        try:            await asyncio.to_thread(self.download_and_extract)        except KeyError as e:            print(f"Info Could Not Be Returned From The Song. Check JSON. Song Has Been Downloaded! \n{e}", tag="ERROR", tag_color="red", color="white")            self.logger.warning(msg=f"[WARNING] Info Could Not Be Returned From The Song. Check JSON. Song Has Been Downloaded. {e}")            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description=f"Error With Returning Information From The Song. Check JSON. \nSong Has Been Downloaded!\n{e}", colour=Color.red(), timestamp=True)            await ctx.channel.send(embed=embed)        except Exception as e:            print(f"Info Could Not Be Returned From The Song. Check JSON. Song Has Been Downloaded! {e}", tag="ERROR", tag_color="red", color="white")            self.logger.warning(msg=f"[WARNING] Info Could Not Be Returned From The Song. Check JSON. Song Has Been Downloaded. {e}")            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description=f"Error With Returning Information From The Song. Check JSON. \nSong Has Been Downloaded!\n{e}", colour=Color.red(), timestamp=True)            await ctx.channel.send(embed=embed)        embed = EmbedGenerator.generate_simple_message_embed(description=f"Successfully Downloaded {self.info['entries'][0]['title']}", colour=Color.green())        await msg_.edit(embed=embed)        print(f"Downloaded {self.info['entries'][0]['title']} - {self.info['entries'][0]['webpage_url']}", tag="SUCCESS", tag_color="green", color="white")        self.logger.info(msg=f"[SUCCESS] Downloaded {self.info['entries'][0]['title']} - {self.info['entries'][0]['webpage_url']}")        if ctx.author.voice is not None:            await ctx.send(view=PlayDownloadedSongButtonView(ctx=ctx, bot=self.bot, file=f'{self.songs_dir}{str(self.info['entries'][0]['id'])}.mp3', file_info=f'{self.songs_info_dir}{str(self.info['entries'][0]['id'])}.json', url=self.url))    def download_and_extract(self):        with yt_dlp.YoutubeDL(self.ydl_opts) as ydl:            print(f"Song: {self.search_query}", tag="DOWNLOADING", tag_color="blue", color="white")            self.logger.info(msg=f"[DOWNLOADING] Song: {self.search_query}")            self.info = ydl.extract_info(f"ytsearch:{self.search_query}", download=True)            filename = f'/Users/eddie/PycharmProjects/FingerBangThePoonTang2Bot/songs_info/{str(self.info['entries'][0]['id']).replace('\"', "")}.json'            if not os.path.exists(filename):                with open(filename, 'w', encoding='utf-8') as f:                    json.dump(self.info['entries'][0], f, ensure_ascii=False, indent=4)                    print(f"Song Info File: {self.search_query}", tag="SUCCESS", tag_color="green", color="white")                    self.logger.info(msg=f"[DOWNLOADING] Song: {self.search_query}")            self.url = self.info['entries'][0]['webpage_url']            return self.info['entries'][0]['webpage_url']            # return self.info['url']async def setup(bot: commands.Bot):    await bot.add_cog(DownloadSongCommand(bot))